SELECT *, AVG(salary) OVER (PARTITION BY manager_id, level ORDER BY hire_date, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS salary_avg_2_prior, NTILE(5) OVER (ORDER BY salary DESC, id) AS salary_bucket, LEAD(salary, 1) OVER (ORDER BY hire_date, id) AS next_salary, ROUND(salary / SUM(salary) OVER (PARTITION BY manager_id), 4) AS salary_share, MAX(salary) OVER (PARTITION BY manager_id, dept_id) AS manager_id_max_salary FROM employees
